use std::io::{self, BufRead, Write};
use std::process::{Command, Stdio};
use std::fs;
use clap::{Parser, ValueEnum};
use serde::Deserialize;

mod highlighter;
use highlighter::Highlighter;

#[derive(Parser, Debug)]
#[command(name = "tspin", version = "5.6.0", about = "A log file highlighter")]
struct Args {
    /// Filepath
    #[arg(value_name = "FILE")]
    file: Option<String>,

    /// Follow the contents of a file
    #[arg(short = 'f', long = "follow")]
    follow: bool,

    /// Print the output to stdout
    #[arg(short = 'p', long = "print")]
    print: bool,

    /// Provide a custom path to a configuration file
    #[arg(long = "config-path", value_name = "CONFIG_PATH")]
    config_path: Option<String>,

    /// Run command and view the output in a pager
    #[arg(short = 'e', long = "exec", value_name = "EXEC")]
    exec: Option<String>,

    /// Highlights in the form color:word1,word2
    #[arg(
        long = "highlight",
        value_name = "COLOR_WORD",
        value_parser = parse_highlight,
    )]
    highlight: Vec<(HighlightColor, Vec<String>)>,

    /// Enable specific highlighters
    #[arg(
        long = "enable",
        value_name = "ENABLED_HIGHLIGHTERS",
        value_delimiter = ',',
        value_enum,
    )]
    enable: Vec<HighlightGroup>,

    /// Disable specific highlighters
    #[arg(
        long = "disable",
        value_name = "DISABLED_HIGHLIGHTERS",
        value_delimiter = ',',
        value_enum,
    )]
    disable: Vec<HighlightGroup>,

    /// Disable the highlighting of all builtin keyword groups (booleans, nulls, log severities and common REST verbs)
    #[arg(long = "disable-builtin-keywords")]
    disable_builtin_keywords: bool,

    /// Override the default pager command used by tspin. (e.g. `--pager="ov -f [FILE]"`)
    #[arg(long = "pager", value_name = "PAGER", env = "TAILSPIN_PAGER")]
    pager: Option<String>,
}

#[derive(Debug, Clone, ValueEnum, PartialEq)]
enum HighlightGroup {
    Numbers,
    Urls,
    Pointers,
    Dates,
    Paths,
    Quotes,
    #[value(name = "key-value-pairs")]
    KeyValuePairs,
    Uuids,
    #[value(name = "ip-addresses")]
    IpAddresses,
    Processes,
    Json,
}

#[derive(Debug, Clone, ValueEnum)]
enum HighlightColor {
    Red,
    Green,
    Yellow,
    Blue,
    Magenta,
    Cyan,
}

fn parse_highlight(s: &str) -> Result<(HighlightColor, Vec<String>), String> {
    let parts: Vec<&str> = s.splitn(2, ':').collect();
    if parts.len() != 2 {
        return Err(format!("Invalid highlight format: {}", s));
    }
    let color = match parts[0] {
        "red" => HighlightColor::Red,
        "green" => HighlightColor::Green,
        "yellow" => HighlightColor::Yellow,
        "blue" => HighlightColor::Blue,
        "magenta" => HighlightColor::Magenta,
        "cyan" => HighlightColor::Cyan,
        c => return Err(format!("Unknown color: {}", c)),
    };
    let words: Vec<String> = parts[1].split(',').map(|w| w.to_string()).collect();
    Ok((color, words))
}

#[derive(Debug, Deserialize, Default)]
struct Config {
    #[serde(default)]
    keywords: Vec<KeywordGroup>,
}

#[derive(Debug, Deserialize)]
struct KeywordGroup {
    words: Vec<String>,
    style: StyleConfig,
}

#[derive(Debug, Deserialize, Default)]
struct StyleConfig {
    #[serde(default)]
    fg: Option<ColorConfig>,
    #[serde(default)]
    bg: Option<ColorConfig>,
    #[serde(default)]
    bold: bool,
    #[serde(default)]
    italic: bool,
    #[serde(default)]
    underline: bool,
    #[serde(default)]
    dim: bool,
}

#[derive(Debug, Deserialize, Clone, PartialEq)]
#[serde(rename_all = "snake_case")]
enum ColorConfig {
    Default,
    Black,
    Red,
    Green,
    Yellow,
    Blue,
    Magenta,
    Cyan,
    White,
    BrightBlack,
    BrightRed,
    BrightGreen,
    BrightYellow,
    BrightBlue,
    BrightMagenta,
    BrightCyan,
    BrightWhite,
}

impl ColorConfig {
    fn fg_code(&self) -> u8 {
        match self {
            ColorConfig::Default => 39,
            ColorConfig::Black => 30,
            ColorConfig::Red => 31,
            ColorConfig::Green => 32,
            ColorConfig::Yellow => 33,
            ColorConfig::Blue => 34,
            ColorConfig::Magenta => 35,
            ColorConfig::Cyan => 36,
            ColorConfig::White => 37,
            ColorConfig::BrightBlack => 90,
            ColorConfig::BrightRed => 91,
            ColorConfig::BrightGreen => 92,
            ColorConfig::BrightYellow => 93,
            ColorConfig::BrightBlue => 94,
            ColorConfig::BrightMagenta => 95,
            ColorConfig::BrightCyan => 96,
            ColorConfig::BrightWhite => 97,
        }
    }

    fn bg_code(&self) -> u8 {
        match self {
            ColorConfig::Default => 49,
            ColorConfig::Black => 40,
            ColorConfig::Red => 41,
            ColorConfig::Green => 42,
            ColorConfig::Yellow => 43,
            ColorConfig::Blue => 44,
            ColorConfig::Magenta => 45,
            ColorConfig::Cyan => 46,
            ColorConfig::White => 47,
            ColorConfig::BrightBlack => 100,
            ColorConfig::BrightRed => 101,
            ColorConfig::BrightGreen => 102,
            ColorConfig::BrightYellow => 103,
            ColorConfig::BrightBlue => 104,
            ColorConfig::BrightMagenta => 105,
            ColorConfig::BrightCyan => 106,
            ColorConfig::BrightWhite => 107,
        }
    }
}

fn load_config(path: &str) -> Result<Config, String> {
    let content = fs::read_to_string(path)
        .map_err(|_| format!("could not find the TOML file"))?;
    toml::from_str(&content).map_err(|e| e.to_string())
}

fn process_lines<R: BufRead, W: Write>(
    reader: R,
    writer: &mut W,
    hl: &Highlighter,
) {
    for line in reader.lines() {
        match line {
            Ok(l) => {
                let highlighted = hl.highlight_line(&l);
                writeln!(writer, "{}", highlighted).ok();
            }
            Err(_) => break,
        }
    }
}

fn main() {
    let args = Args::parse();

    // Load config
    let config = if let Some(ref config_path) = args.config_path {
        match load_config(config_path) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("Error: {}", format_error(&e));
                std::process::exit(1);
            }
        }
    } else {
        // Try default config path
        let default_path = get_default_config_path();
        if let Some(path) = default_path {
            if std::path::Path::new(&path).exists() {
                match load_config(&path) {
                    Ok(c) => c,
                    Err(_) => Config::default(),
                }
            } else {
                Config::default()
            }
        } else {
            Config::default()
        }
    };

    // Determine which highlighters to use
    let enabled_groups = compute_enabled_groups(&args);

    // Build highlighter
    let hl = Highlighter::new(
        &config,
        &enabled_groups,
        &args.highlight,
        args.disable_builtin_keywords,
    );

    let stdout = io::stdout();
    let mut out = stdout.lock();

    if let Some(ref exec_cmd) = args.exec {
        // Run command and highlight output
        run_exec(exec_cmd, &hl, &args, &mut out);
    } else if let Some(ref filepath) = args.file {
        // Read from file
        if args.follow {
            // Follow mode - tail -f like behavior
            follow_file(filepath, &hl, &args, &mut out);
        } else {
            let file = match fs::File::open(filepath) {
                Ok(f) => f,
                Err(e) => {
                    eprintln!("Error opening file: {}", e);
                    std::process::exit(1);
                }
            };
            let reader = io::BufReader::new(file);
            if args.print {
                process_lines(reader, &mut out, &hl);
            } else {
                // Use pager
                use_pager(filepath, &hl, &args);
            }
        }
    } else {
        // Read from stdin
        let stdin = io::stdin();
        let reader = stdin.lock();
        process_lines(reader, &mut out, &hl);
    }
}

fn format_error(msg: &str) -> String {
    // Format error similar to original: using miette-style output
    let lines: Vec<&str> = msg.lines().collect();
    if lines.is_empty() {
        return format!("  \u{00D7} {}", msg);
    }
    let mut result = format!("  \u{00D7} {}\n", lines[0]);
    for line in &lines[1..] {
        result.push_str(&format!("  \u{2502}   {}\n", line));
    }
    result
}

fn get_default_config_path() -> Option<String> {
    if let Ok(xdg_config) = std::env::var("XDG_CONFIG_HOME") {
        Some(format!("{}/tailspin/theme.toml", xdg_config))
    } else if let Ok(home) = std::env::var("HOME") {
        Some(format!("{}/.config/tailspin/theme.toml", home))
    } else {
        None
    }
}

fn compute_enabled_groups(args: &Args) -> std::collections::HashSet<HighlightGroup> {
    use HighlightGroup::*;
    let all_groups = vec![
        Numbers, Urls, Pointers, Dates, Paths, Quotes, KeyValuePairs, Uuids, IpAddresses, Processes, Json,
    ];

    if !args.enable.is_empty() {
        // Only enable specified groups
        args.enable.iter().cloned().collect()
    } else if !args.disable.is_empty() {
        // Enable all except disabled
        let disabled: std::collections::HashSet<&HighlightGroup> = args.disable.iter().collect();
        all_groups.into_iter().filter(|g| !disabled.contains(g)).collect()
    } else {
        // Enable all
        all_groups.into_iter().collect()
    }
}

fn run_exec(cmd: &str, hl: &Highlighter, args: &Args, out: &mut impl Write) {
    // Run command in shell, capture output, highlight it
    let mut child = Command::new("sh")
        .arg("-c")
        .arg(cmd)
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit())
        .spawn()
        .expect("Failed to start command");

    if let Some(stdout) = child.stdout.take() {
        let reader = io::BufReader::new(stdout);
        if args.print {
            process_lines(reader, out, hl);
        } else {
            // Write to temp file for pager
            let tmp_path = write_to_temp(reader, hl);
            open_pager(&tmp_path, args);
        }
    }
    child.wait().ok();
}

fn follow_file(filepath: &str, hl: &Highlighter, args: &Args, out: &mut impl Write) {
    // Simple follow mode
    use std::io::Read;
    let file = match fs::File::open(filepath) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("Error opening file: {}", e);
            std::process::exit(1);
        }
    };
    let mut reader = io::BufReader::new(file);
    let mut line = String::new();
    loop {
        line.clear();
        match reader.read_line(&mut line) {
            Ok(0) => {
                // EOF, wait for more
                std::thread::sleep(std::time::Duration::from_millis(100));
            }
            Ok(_) => {
                let trimmed = line.trim_end_matches('\n').trim_end_matches('\r');
                let highlighted = hl.highlight_line(trimmed);
                writeln!(out, "{}", highlighted).ok();
                out.flush().ok();
            }
            Err(_) => break,
        }
    }
}

fn write_to_temp<R: BufRead>(reader: R, hl: &Highlighter) -> String {
    let tmp_path = format!("/tmp/tspin-{}", std::process::id());
    let mut tmp_file = fs::File::create(&tmp_path).expect("Failed to create temp file");
    for line in reader.lines() {
        if let Ok(l) = line {
            let highlighted = hl.highlight_line(&l);
            writeln!(tmp_file, "{}", highlighted).ok();
        }
    }
    tmp_path
}

fn use_pager(filepath: &str, hl: &Highlighter, args: &Args) {
    // Read file, highlight, write to temp, open in less
    let file = fs::File::open(filepath).expect("Failed to open file");
    let reader = io::BufReader::new(file);
    let tmp_path = write_to_temp(reader, hl);
    open_pager(&tmp_path, args);
    fs::remove_file(&tmp_path).ok();
}

fn open_pager(tmp_path: &str, args: &Args) {
    let pager_cmd = if let Some(ref pager) = args.pager {
        pager.replace("[FILE]", tmp_path)
    } else {
        format!("less -R {}", tmp_path)
    };

    Command::new("sh")
        .arg("-c")
        .arg(&pager_cmd)
        .status()
        .ok();
}
