            let reader = io::BufReader::new(file);
            if args.print {
                process_lines(reader, &mut out, &hl);
            } else {
                // Use pager
                use_pager(filepath, &hl, &args);
            }
        }
    } else {
        // Read from stdin
        let stdin = io::stdin();
        let reader = stdin.lock();
        process_lines(reader, &mut out, &hl);
    }
}

fn format_error(msg: &str) -> String {
    // Format error similar to original: using miette-style output
    let lines: Vec<&str> = msg.lines().collect();
    if lines.is_empty() {
        return format!("  \u{00D7} {}", msg);
    }
    let mut result = format!("  \u{00D7} {}\n", lines[0]);
    for line in &lines[1..] {
        result.push_str(&format!("  \u{2502}   {}\n", line));
    }
    result
}

fn get_default_config_path() -> Option<String> {
    if let Ok(xdg_config) = std::env::var("XDG_CONFIG_HOME") {
        Some(format!("{}/tailspin/theme.toml", xdg_config))
    } else if let Ok(home) = std::env::var("HOME") {
        Some(format!("{}/.config/tailspin/theme.toml", home))
    } else {
        None
    }
}

fn compute_enabled_groups(args: &Args) -> std::collections::HashSet<HighlightGroup> {
    use HighlightGroup::*;
    let all_groups = vec![
        Numbers, Urls, Pointers, Dates, Paths, Quotes, KeyValuePairs, Uuids, IpAddresses, Processes, Json,
    ];

    if !args.enable.is_empty() {
        // Only enable specified groups
        args.enable.iter().cloned().collect()
    } else if !args.disable.is_empty() {
        // Enable all except disabled
        let disabled: std::collections::HashSet<&HighlightGroup> = args.disable.iter().collect();
        all_groups.into_iter().filter(|g| !disabled.contains(g)).collect()
    } else {
        // Enable all
        all_groups.into_iter().collect()
    }
}

fn run_exec(cmd: &str, hl: &Highlighter, args: &Args, out: &mut impl Write) {
    // Run command in shell, capture output, highlight it
    let mut child = Command::new("sh")
        .arg("-c")
        .arg(cmd)
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit())
        .spawn()
        .expect("Failed to start command");

    if let Some(stdout) = child.stdout.take() {
        let reader = io::BufReader::new(stdout);
        if args.print {
            process_lines(reader, out, hl);
        } else {
            // Write to temp file for pager
            let tmp_path = write_to_temp(reader, hl);
            open_pager(&tmp_path, args);
        }
    }
    child.wait().ok();
}

fn follow_file(filepath: &str, hl: &Highlighter, args: &Args, out: &mut impl Write) {
    // Simple follow mode
    use std::io::Read;
    let file = match fs::File::open(filepath) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("Error opening file: {}", e);
            std::process::exit(1);
        }
    };
    let mut reader = io::BufReader::new(file);
    let mut line = String::new();
    loop {
        line.clear();
        match reader.read_line(&mut line) {
            Ok(0) => {
                // EOF, wait for more
                std::thread::sleep(std::time::Duration::from_millis(100));
            }
            Ok(_) => {
                let trimmed = line.trim_end_matches('\n').trim_end_matches('\r');
                let highlighted = hl.highlight_line(trimmed);
                writeln!(out, "{}", highlighted).ok();
                out.flush().ok();
            }
            Err(_) => break,
        }
    }
}

fn write_to_temp<R: BufRead>(reader: R, hl: &Highlighter) -> String {
    let tmp_path = format!("/tmp/tspin-{}", std::process::id());
    let mut tmp_file = fs::File::create(&tmp_path).expect("Failed to create temp file");
    for line in reader.lines() {
        if let Ok(l) = line {
            let highlighted = hl.highlight_line(&l);
            writeln!(tmp_file, "{}", highlighted).ok();
        }
    }
    tmp_path
}

fn use_pager(filepath: &str, hl: &Highlighter, args: &Args) {
    // Read file, highlight, write to temp, open in less
    let file = fs::File::open(filepath).expect("Failed to open file");
    let reader = io::BufReader::new(file);
    let tmp_path = write_to_temp(reader, hl);
    open_pager(&tmp_path, args);
    fs::remove_file(&tmp_path).ok();
}

fn open_pager(tmp_path: &str, args: &Args) {
    let pager_cmd = if let Some(ref pager) = args.pager {
        pager.replace("[FILE]", tmp_path)
    } else {
        format!("less -R {}", tmp_path)
    };

    Command::new("sh")
        .arg("-c")
        .arg(&pager_cmd)
        .status()
        .ok();
}
