// HTTP Methods
static HTTP_METHODS_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r" (GET|POST|PUT|DELETE|PATCH) ").unwrap()
});

fn apply_http_methods(segments: &[Segment]) -> Vec<Segment> {
    let mut result = Vec::new();
    for seg in segments {
        if !seg.is_plain() {
            result.push(seg.clone());
            continue;
