// URLs
static URL_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"(https?)://([^\s/?#]+)(/[^\s?#]*)?(?:\?([^\s#]*))?").unwrap()
});

fn apply_urls(segments: &[Segment]) -> Vec<Segment> {
    let mut result = Vec::new();
    for seg in segments {
        if !seg.is_plain() {
            result.push(seg.clone());
            continue;
        }
        let text = match seg {
            Segment::Plain(s) => s.as_str(),
            _ => unreachable!(),
        };

        let re = &*URL_RE;
        let mut last_end = 0;
        for cap in re.captures_iter(text) {
            let full = cap.get(0).unwrap();
            let start = full.start();
            let end = full.end();

            if start > last_end {
                result.push(Segment::Plain(text[last_end..start].to_string()));
            }

            let scheme = cap.get(1).map(|m| m.as_str()).unwrap_or("");
            let host = cap.get(2).map(|m| m.as_str()).unwrap_or("");
            let path = cap.get(3).map(|m| m.as_str()).unwrap_or("");
            let query = cap.get(4).map(|m| m.as_str());

            let scheme_style = if scheme == "https" { "2;32" } else { "2;31" };
            let mut highlighted = format!(
                "{}://{}",
                make_ansi(scheme, scheme_style),
                make_ansi(host, "2;34")
            );

            if !path.is_empty() {
                highlighted.push_str(&make_ansi(path, "34"));
            }

            if let Some(q) = query {
                // Parse query params
                highlighted.push_str(&make_ansi("?", "31"));
                let parts: Vec<&str> = q.split('&').collect();
                for (i, part) in parts.iter().enumerate() {
                    if i > 0 {
                        highlighted.push_str(&make_ansi("&", "31"));
                    }
                    if let Some(eq_pos) = part.find('=') {
                        let key = &part[..eq_pos];
                        let val = &part[eq_pos+1..];
                        highlighted.push_str(&make_ansi(key, "35"));
                        highlighted.push_str(&make_ansi("=", "31"));
                        highlighted.push_str(&make_ansi(val, "36"));
                    } else {
                        highlighted.push_str(&make_ansi(part, "35"));
                    }
                }
            }

            result.push(Segment::Highlighted(highlighted));
            last_end = end;
        }

        if last_end < text.len() {
            result.push(Segment::Plain(text[last_end..].to_string()));
        }
    }
    result
}

