fn colorize_path(path: &str) -> String {
    let mut result = String::new();
    if path.starts_with('~') {
        result.push_str(&make_ansi("~", "32"));
        let rest = &path[1..];
        result.push_str(&colorize_path_rest(rest));
    } else {
        result.push_str(&colorize_path_rest(path));
    }
    result
}

fn colorize_path_rest(path: &str) -> String {
    let mut result = String::new();
    let parts: Vec<&str> = path.split('/').collect();
    for (i, part) in parts.iter().enumerate() {
        if i == 0 && part.is_empty() {
            // Leading slash
            result.push_str(&make_ansi("/", "33"));
        } else if i == 0 {
            // No leading slash (shouldn't happen with our regex)
            result.push_str(&make_ansi(part, "32"));
        } else if !part.is_empty() {
            result.push_str(&make_ansi("/", "33"));
            result.push_str(&make_ansi(part, "32"));
        } else {
            // Trailing slash
            result.push('/');
        }
    }
    result
}

