// Quotes
fn apply_quotes(segments: &[Segment], original_line: &str) -> Vec<Segment> {
    // Check if the line (stripped) is a single quoted string
    let trimmed = original_line.trim();
    let is_single_quote = trimmed.starts_with('"') && trimmed.ends_with('"')
        && trimmed.len() > 1
        && trimmed[1..trimmed.len()-1].find('"').is_none();

    // Also check if there's only whitespace outside the quotes
    let is_only_quote = if is_single_quote {
        original_line.trim() == trimmed
    } else {
        false
    };

    // Find all quoted strings in the remaining plain segments
    apply_regex_to_segments(segments.to_vec(), &Regex::new(r#""[^"]*""#).unwrap(), move |matched| {
        if is_only_quote && matched == trimmed {
            // Single quote case: dim quotes, plain content
            let inner = &matched[1..matched.len()-1];
            vec![Segment::Highlighted(format!(
                "{}{}{}",
                make_ansi("\"", "2"),
                inner,
                make_ansi("\"", "2")
            ))]
        } else {
            // Yellow for the whole quoted string
            vec![Segment::Highlighted(make_ansi(matched, "33"))]
        }
    })
}

// Inline JSON
fn apply_inline_json(segments: &[Segment]) -> Vec<Segment> {
    // Find JSON-like structures in the text that weren't full-line JSON
    apply_regex_to_segments(segments.to_vec(), &Regex::new(r#"\{"[^{}]*"\}"#).unwrap(), |matched| {
        // Color the strings yellow, leave structural chars plain
        // This is a simplified version
        let highlighted = colorize_inline_json(matched);
        vec![Segment::Highlighted(highlighted)]
    })
}

fn colorize_inline_json(json: &str) -> String {
    let mut result = String::new();
    let mut in_string = false;
    let mut string_start = 0;
    let chars: Vec<char> = json.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        let ch = chars[i];
        if !in_string && ch == '"' {
            in_string = true;
            string_start = i;
        } else if in_string && ch == '"' && (i == 0 || chars[i-1] != '\\') {
            // End of string
            let s: String = chars[string_start..=i].iter().collect();
            result.push_str(&make_ansi(&s, "33"));
            in_string = false;
        } else if !in_string {
            result.push(ch);
        }
        i += 1;
    }
    result
}

// Full JSON formatter
fn try_highlight_full_json(line: &str) -> Option<String> {
    let trimmed = line.trim();
    // Try to parse as JSON
    let value: serde_json::Value = serde_json::from_str(trimmed).ok()?;

    // Format the JSON with our styling
    let formatted = format_json_value(&value);
    Some(formatted)
}

fn format_json_value(value: &serde_json::Value) -> String {
    match value {
        serde_json::Value::Object(map) => {
            let mut result = String::new();
            result.push_str(&make_ansi("{", "2"));
            result.push(' ');
            let pairs: Vec<String> = map.iter().map(|(k, v)| {
                let key_str = format!(
                    "{}{}{}{}{}",
                    make_ansi("\"", "2"),
                    make_ansi(k, "2"),
                    make_ansi("\"", "2"),
                    make_ansi(":", "2"),
                    " "
                );
                format!("{}{}", key_str, format_json_value(v))
            }).collect();
            result.push_str(&pairs.join(&format!("{} ", make_ansi(",", "2"))));
            result.push(' ');
            result.push_str(&make_ansi("}", "2"));
            result
        }
        serde_json::Value::Array(arr) => {
            let mut result = String::new();
            result.push_str(&make_ansi("[", "2"));
            let items: Vec<String> = arr.iter().map(|v| format_json_value(v)).collect();
            result.push_str(&items.join(&format!("{} ", make_ansi(",", "2"))));
            result.push_str(&make_ansi("]", "2"));
            result
        }
        serde_json::Value::String(s) => {
            format!(
                "{}{}{}",
                make_ansi("\"", "2"),
                s,
                make_ansi("\"", "2")
            )
        }
        serde_json::Value::Number(n) => {
            make_ansi(&n.to_string(), "36")
        }
        serde_json::Value::Bool(b) => {
            make_ansi(&b.to_string(), "3;31")
        }
        serde_json::Value::Null => {
            make_ansi("null", "3;31")
        }
    }
}
