use std::collections::HashSet;
use regex::Regex;
use once_cell::sync::Lazy;

use crate::{Config, HighlightColor, HighlightGroup, KeywordGroup, StyleConfig, ColorConfig};

pub struct Highlighter {
    keyword_groups: Vec<CompiledKeywordGroup>,
    enabled_groups: HashSet<HighlightGroup>,
    custom_highlights: Vec<(HighlightColor, Vec<String>)>,
    disable_builtin_keywords: bool,
}

struct CompiledKeywordGroup {
    words: Vec<String>,
    style: StyleConfig,
}

impl Highlighter {
    pub fn new(
        config: &Config,
        enabled_groups: &HashSet<HighlightGroup>,
        custom_highlights: &[(HighlightColor, Vec<String>)],
        disable_builtin_keywords: bool,
    ) -> Self {
        let keyword_groups = config.keywords.iter()
            .map(|kg| CompiledKeywordGroup {
                words: kg.words.clone(),
                style: StyleConfig {
                    fg: kg.style.fg.clone(),
                    bg: kg.style.bg.clone(),
                    bold: kg.style.bold,
                    italic: kg.style.italic,
                    underline: kg.style.underline,
                    dim: kg.style.dim,
                },
            })
            .collect();

        Highlighter {
            keyword_groups,
            enabled_groups: enabled_groups.clone(),
            custom_highlights: custom_highlights.to_vec(),
            disable_builtin_keywords,
        }
    }

    pub fn highlight_line(&self, line: &str) -> String {
        // Highlighter pipeline - applies in priority order
        // Each highlighter works on segments not yet highlighted

        // Check if this line is a full JSON line
        let trimmed = line.trim();
        if !trimmed.is_empty()
            && (trimmed.starts_with('{') || trimmed.starts_with('['))
            && self.enabled_groups.contains(&HighlightGroup::Json)
        {
            // Try to parse as full JSON
            if let Some(highlighted) = try_highlight_full_json(line) {
                return highlighted;
            }
        }

        // Apply highlighters in sequence, tracking which regions are already highlighted
        let mut segments: Vec<Segment> = vec![Segment::Plain(line.to_string())];

        // Apply custom highlights first
        for (color, words) in &self.custom_highlights {
            segments = apply_custom_highlight(&segments, color, words);
        }

        // Apply keyword groups from config
        for kg in &self.keyword_groups {
            segments = apply_keyword_group(&segments, &kg.words, &kg.style);
        }

        // Apply builtin highlighters
        if !self.disable_builtin_keywords {
            // HTTP methods (applied as whole words in context)
            segments = apply_http_methods(&segments);
        }

        if self.enabled_groups.contains(&HighlightGroup::Dates) {
            segments = apply_dates(&segments);
        }

        if self.enabled_groups.contains(&HighlightGroup::IpAddresses) {
            segments = apply_ip_addresses(&segments);
        }

        if self.enabled_groups.contains(&HighlightGroup::Pointers) {
            segments = apply_pointers(&segments);
        }

        if self.enabled_groups.contains(&HighlightGroup::Uuids) {
            segments = apply_uuids(&segments);
        }

        if self.enabled_groups.contains(&HighlightGroup::Processes) {
            segments = apply_processes(&segments);
        }

        if self.enabled_groups.contains(&HighlightGroup::Urls) {
            segments = apply_urls(&segments);
        }

        if self.enabled_groups.contains(&HighlightGroup::Paths) {
            segments = apply_paths(&segments);
        }

        if self.enabled_groups.contains(&HighlightGroup::Numbers) {
            segments = apply_numbers(&segments);
        }

        if !self.disable_builtin_keywords {
            segments = apply_severity_levels(&segments);
            segments = apply_boolean_null(&segments);
        }

        if self.enabled_groups.contains(&HighlightGroup::KeyValuePairs) {
            segments = apply_key_value_pairs(&segments);
        }

        // Inline JSON (not full JSON, but JSON-like structures in text)
        if self.enabled_groups.contains(&HighlightGroup::Json) {
            segments = apply_inline_json(&segments);
        }

        if self.enabled_groups.contains(&HighlightGroup::Quotes) {
            segments = apply_quotes(&segments, line);
        }

        // Render all segments
        segments.iter().map(|s| s.render()).collect::<Vec<_>>().join("")
    }
}

#[derive(Clone, Debug)]
enum Segment {
    Plain(String),
    Highlighted(String), // Already has ANSI codes, don't process further
}

impl Segment {
    fn render(&self) -> String {
        match self {
            Segment::Plain(s) => s.clone(),
            Segment::Highlighted(s) => s.clone(),
        }
    }

    fn is_plain(&self) -> bool {
        matches!(self, Segment::Plain(_))
    }

    fn as_str(&self) -> &str {
        match self {
            Segment::Plain(s) => s.as_str(),
            Segment::Highlighted(s) => s.as_str(),
        }
    }
}

fn make_ansi(text: &str, style: &str) -> String {
    format!("\x1b[{}m{}\x1b[0m", style, text)
}

fn apply_regex_to_segments<F>(segments: Vec<Segment>, pattern: &Regex, handler: F) -> Vec<Segment>
where
    F: Fn(&str) -> Vec<Segment>,
{
    let mut result = Vec::new();
    for seg in segments {
        if !seg.is_plain() {
            result.push(seg);
            continue;
        }
        let text = match &seg {
            Segment::Plain(s) => s.clone(),
            _ => unreachable!(),
        };
        let mut last_end = 0;
        for m in pattern.find_iter(&text) {
            if m.start() > last_end {
                result.push(Segment::Plain(text[last_end..m.start()].to_string()));
            }
            let matched_text = &text[m.start()..m.end()];
            let mut replacement = handler(matched_text);
            result.append(&mut replacement);
            last_end = m.end();
        }
        if last_end < text.len() {
            result.push(Segment::Plain(text[last_end..].to_string()));
        }
    }
    result
}

fn apply_custom_highlight(
    segments: &[Segment],
    color: &HighlightColor,
    words: &[String],
) -> Vec<Segment> {
    let color_code = match color {
        HighlightColor::Red => "31",
        HighlightColor::Green => "32",
        HighlightColor::Yellow => "33",
        HighlightColor::Blue => "34",
        HighlightColor::Magenta => "35",
        HighlightColor::Cyan => "36",
    };

    let mut segs = segments.to_vec();
    for word in words {
        // Escape the word for regex - treat as literal
        let escaped = regex::escape(word);
        // Match as word (not necessarily word-boundary, but literal)
        let pattern_str = escaped;
        let pattern = Regex::new(&pattern_str).unwrap();
        segs = apply_regex_to_segments(segs, &pattern, |matched| {
            vec![Segment::Highlighted(make_ansi(matched, color_code))]
        });
    }
    segs
}

fn apply_keyword_group(segments: &[Segment], words: &[String], style: &StyleConfig) -> Vec<Segment> {
    let has_bg = style.bg.is_some();

    // Build style string
    let mut codes: Vec<String> = Vec::new();
    if style.bold { codes.push("1".to_string()); }
    if style.italic { codes.push("3".to_string()); }
    if style.underline { codes.push("4".to_string()); }
    if let Some(ref bg) = style.bg {
        codes.push(bg.bg_code().to_string());
    }
    if let Some(ref fg) = style.fg {
        codes.push(fg.fg_code().to_string());
    }

    if codes.is_empty() {
        return segments.to_vec();
    }

    let style_str = codes.join(";");

    let mut segs = segments.to_vec();
    for word in words {
        let escaped = regex::escape(word);
        let pattern = Regex::new(&escaped).unwrap();
        let style_str_clone = style_str.clone();
        let has_bg_clone = has_bg;
        segs = apply_regex_to_segments(segs, &pattern, move |matched| {
            let display = if has_bg_clone {
                format!(" {} ", matched)
            } else {
                matched.to_string()
            };
            vec![Segment::Highlighted(make_ansi(&display, &style_str_clone))]
        });
    }
    segs
}

// HTTP Methods
static HTTP_METHODS_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r" (GET|POST|PUT|DELETE|PATCH) ").unwrap()
});

fn apply_http_methods(segments: &[Segment]) -> Vec<Segment> {
    let mut result = Vec::new();
    for seg in segments {
        if !seg.is_plain() {
            result.push(seg.clone());
            continue;
        }
        let text = match seg {
            Segment::Plain(s) => s.as_str(),
            _ => unreachable!(),
        };

        // For HTTP methods we need to match " METHOD " but we also need to handle
        // the case where the method is at the start of the line without leading space
        let re = &*HTTP_METHODS_RE;
        let mut last_end = 0;
        // Also handle start of line (no leading space)
        let extended_re = Regex::new(r"(?:^| )(GET|POST|PUT|DELETE|PATCH)(?:$| )").unwrap();

        let mut matches: Vec<(usize, usize, &str)> = Vec::new();
        for m in extended_re.captures_iter(text) {
            let full_match = m.get(0).unwrap();
            let method = m.get(1).unwrap();
            matches.push((full_match.start(), full_match.end(), method.as_str()));
        }

        if matches.is_empty() {
            result.push(seg.clone());
            continue;
        }

        // Process matches handling overlap issues
        let mut segs: Vec<Segment> = Vec::new();
        last_end = 0;
        for (start, end, method) in matches {
            // Include leading space in the output
            let has_leading_space = start > 0 || (start == 0 && text.starts_with(' '));
            let has_trailing_space = end < text.len();

            let method_color = match method {
                "GET" => "42;30",
                "POST" => "43;30",
                "PUT" => "45;30",
                "DELETE" => "41;30",
                "PATCH" => "45;30",
                _ => "42;30",
            };

            // The character before the method (space) is part of the match but not highlighted
            let actual_start = if start < last_end { last_end } else { start };
            if actual_start > last_end {
                segs.push(Segment::Plain(text[last_end..actual_start].to_string()));
            }

            // Extract leading space from match
            let match_text = &text[start..end];
            let method_in_match = match_text.trim();
            let prefix = if match_text.starts_with(' ') { " " } else { "" };
            let suffix = if match_text.ends_with(' ') { " " } else { "" };

            if !prefix.is_empty() {
                segs.push(Segment::Plain(prefix.to_string()));
            }
            segs.push(Segment::Highlighted(make_ansi(&format!(" {} ", method_in_match), method_color)));
            if !suffix.is_empty() && end == text.len() {
                segs.push(Segment::Plain(suffix.to_string()));
            }
            last_end = end;
        }
        if last_end < text.len() {
            segs.push(Segment::Plain(text[last_end..].to_string()));
        }
        result.extend(segs);
    }
    result
}

// Severity levels
static SEVERITY_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\b(DEBUG|TRACE|INFO|WARN|ERROR)\b").unwrap()
});

fn apply_severity_levels(segments: &[Segment]) -> Vec<Segment> {
    apply_regex_to_segments(segments.to_vec(), &*SEVERITY_RE, |matched| {
        let style = match matched {
            "DEBUG" => "32",
            "TRACE" => "2",
            "INFO" => "37",
            "WARN" => "33",
            "ERROR" => "31",
            _ => "37",
        };
        vec![Segment::Highlighted(make_ansi(matched, style))]
    })
}

// Boolean/null keywords
static BOOL_NULL_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\b(true|false|null)\b").unwrap()
});

fn apply_boolean_null(segments: &[Segment]) -> Vec<Segment> {
    apply_regex_to_segments(segments.to_vec(), &*BOOL_NULL_RE, |matched| {
        vec![Segment::Highlighted(make_ansi(matched, "3;31"))]
    })
}

// Numbers
static NUMBER_RE: Lazy<Regex> = Lazy::new(|| {
    // Match numbers not surrounded by alpha/underscore
    // Matches: integers and decimals (not scientific notation here)
    Regex::new(r"(?<![a-zA-Z_])\d+(?:\.\d+)?(?![a-zA-Z_])").unwrap()
});

fn apply_numbers(segments: &[Segment]) -> Vec<Segment> {
    apply_regex_to_segments(segments.to_vec(), &*NUMBER_RE, |matched| {
        vec![Segment::Highlighted(make_ansi(matched, "36"))]
    })
}

// IPv4 addresses
static IPV4_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\b(?:(?:25[0-5]|2[0-4]\d|1\d{2}|[1-9]\d|\d)\.){3}(?:25[0-5]|2[0-4]\d|1\d{2}|[1-9]\d|\d)\b").unwrap()
});

fn colorize_ipv4(ip: &str) -> String {
    let parts: Vec<&str> = ip.split('.').collect();
    parts.iter().enumerate().map(|(i, part)| {
        let colored = make_ansi(part, "3;34");
        if i < parts.len() - 1 {
            format!("{}{}", colored, make_ansi(".", "31"))
        } else {
            colored
        }
    }).collect::<Vec<_>>().join("")
}

fn apply_ip_addresses(segments: &[Segment]) -> Vec<Segment> {
    let segs = apply_ipv4(segments);
    apply_ipv6(&segs)
}

fn apply_ipv4(segments: &[Segment]) -> Vec<Segment> {
    apply_regex_to_segments(segments.to_vec(), &*IPV4_RE, |matched| {
        vec![Segment::Highlighted(colorize_ipv4(matched))]
    })
}

// IPv6 address - simplified pattern
static IPV6_RE: Lazy<Regex> = Lazy::new(|| {
    // Match IPv6 addresses with various formats
    Regex::new(r"(?:[0-9a-fA-F]{1,4}:){1,7}[0-9a-fA-F]{1,4}|(?:[0-9a-fA-F]{1,4}:)*::(?:[0-9a-fA-F]{1,4}:)*[0-9a-fA-F]{1,4}|(?:[0-9a-fA-F]{1,4}:)*::[0-9a-fA-F]{0,4}|(?:[0-9a-fA-F]{1,4}:){1,7}:|::").unwrap()
});

fn colorize_ipv6(ip: &str) -> String {
    let mut result = String::new();
    for ch in ip.chars() {
        match ch {
            ':' => result.push_str(&make_ansi(":", "31")),
            '0'..='9' => result.push_str(&make_ansi(&ch.to_string(), "3;34")),
            'a'..='f' | 'A'..='F' => result.push_str(&make_ansi(&ch.to_string(), "3;35")),
            _ => result.push(ch),
        }
    }
    result
}

fn apply_ipv6(segments: &[Segment]) -> Vec<Segment> {
    apply_regex_to_segments(segments.to_vec(), &*IPV6_RE, |matched| {
        // Make sure it looks like a real IPv6 (has at least 2 colons or :: )
        let colon_count = matched.chars().filter(|&c| c == ':').count();
        if colon_count < 2 {
            return vec![Segment::Plain(matched.to_string())];
        }
        vec![Segment::Highlighted(colorize_ipv6(matched))]
    })
}

// Pointers
static POINTER_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"0x[0-9a-fA-F]{8}(?:[0-9a-fA-F]{8})?").unwrap()
});

fn colorize_pointer(ptr: &str) -> String {
    // "0" + "x" + hex digits
    let mut result = String::new();
    result.push_str(&make_ansi("0", "3;34"));
    result.push_str(&make_ansi("x", "31"));

    let hex_part = &ptr[2..];
    let total_len = hex_part.len();

    for (i, ch) in hex_part.chars().enumerate() {
        // Insert bullet separator at position 8 for 16-char hex
        if total_len == 16 && i == 8 {
            result.push_str(&make_ansi("\u{2022}", "2"));
        }
        match ch {
