// Processes: name[pid] or (name)[pid]
static PROCESS_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\(?[\w][\w.-]*\)?\[\d+\]").unwrap()
});

fn apply_processes(segments: &[Segment]) -> Vec<Segment> {
    apply_regex_to_segments(segments.to_vec(), &*PROCESS_RE, |matched| {
        // Split into name part and [pid] part
        if let Some(bracket_pos) = matched.rfind('[') {
            let name_part = &matched[..bracket_pos];
            let pid_and_bracket = &matched[bracket_pos..];
            // pid_and_bracket is like "[12345]"
            let pid = &pid_and_bracket[1..pid_and_bracket.len()-1];
            let highlighted = format!(
                "{}{}{}{}",
                make_ansi(name_part, "33"),
                make_ansi("[", "31"),
                make_ansi(pid, "36"),
                make_ansi("]", "31")
            );
            vec![Segment::Highlighted(highlighted)]
        } else {
            vec![Segment::Plain(matched.to_string())]
        }
    })
