        # Boolean/null (builtin keywords)
        if not self.disable_builtin_keywords:
            segments = apply_segments(segments, BOOL_NULL_RE, lambda m: ansi(m.group(0), '3;31'))

        # Key-value pairs
        if 'key-value-pairs' in self.enabled_groups:
            segments = self._apply_kv(segments)

        # Inline JSON
        if 'json' in self.enabled_groups:
            segments = self._apply_inline_json(segments)

        # Quotes
        if 'quotes' in self.enabled_groups:
            segments = self._apply_quotes(segments, line)

        return segments_to_str(segments)

    def _apply_http_methods(self, segments):
        """Apply HTTP method highlighting"""
        pat = HTTP_METHOD_RE
        def replacer(m):
            method = m.group(1)
            colors = {'GET': '42;30', 'POST': '43;30', 'PUT': '45;30', 'DELETE': '41;30', 'PATCH': '45;30'}
            color = colors.get(method, '42;30')
            return ansi(f' {method} ', color)
        return apply_segments(segments, pat, replacer)

    def _apply_processes(self, segments):
        """Apply process name[pid] highlighting"""
        def replacer(m):
            text = m.group(0)
            bracket_pos = text.rfind('[')
            if bracket_pos == -1:
                return text
            name_part = text[:bracket_pos]
            pid_part = text[bracket_pos+1:-1]
            return (ansi(name_part, '33') + ansi('[', '31') + 
                    ansi(pid_part, '36') + ansi(']', '31'))
        return apply_segments(segments, PROCESS_RE, replacer)

    def _apply_urls(self, segments):
        """Apply URL highlighting"""
        return apply_segments(segments, URL_RE, lambda m: colorize_url(m))

    def _apply_paths(self, segments):
        """Apply file path highlighting"""
        return apply_segments(segments, PATH_RE, lambda m: colorize_path(m.group(0)))

    def _apply_kv(self, segments):
        """Apply key-value pair highlighting"""
        def replacer(m):
            text = m.group(0)
            eq_pos = text.index('=')
            key = text[:eq_pos]
            val = text[eq_pos+1:]
            return ansi(key, '2') + ansi('=', '37') + val
        return apply_segments(segments, KV_RE, replacer)

    def _apply_inline_json(self, segments):
        """Apply inline JSON string highlighting"""
        def replacer(m):
            text = m.group(0)
            # Check if it contains quoted strings (making it JSON-like)
            if '"' not in text:
                return text
            return colorize_inline_json_string(text)
        return apply_segments(segments, INLINE_JSON_RE, replacer)

    def _apply_quotes(self, segments, original_line):
        """Apply quote highlighting"""
        # Check if this is a single-quoted string (only whitespace around it)
        stripped = original_line.strip()
        is_single_only = (
            stripped.startswith('"') and 
            stripped.endswith('"') and 
            len(stripped) > 1 and
            '"' not in stripped[1:-1]
        )

        def replacer(m):
            text = m.group(0)
            if is_single_only and text == stripped:
                # Dim quotes, plain content
                inner = text[1:-1]
                return ansi('"', '2') + inner + ansi('"', '2')
            else:
                return ansi(text, '33')

        return apply_segments(segments, QUOTE_RE, replacer)


def parse_args():
    parser = argparse.ArgumentParser(
        prog='tspin',
        description='A log file highlighter',
        add_help=False
    )

    parser.add_argument('file', nargs='?', metavar='FILE', help='Filepath')
    parser.add_argument('-f', '--follow', action='store_true', help='Follow the contents of a file')
    parser.add_argument('-p', '--print', action='store_true', help='Print the output to stdout')
    parser.add_argument('--config-path', metavar='CONFIG_PATH', help='Provide a custom path to a configuration file')
    parser.add_argument('-e', '--exec', metavar='EXEC', help='Run command and view the output in a pager')
    parser.add_argument('--highlight', action='append', metavar='COLOR_WORD', default=[],
                       help='Highlights in the form color:word1,word2')

    ALL_GROUPS = ['numbers', 'urls', 'pointers', 'dates', 'paths', 'quotes', 
                  'key-value-pairs', 'uuids', 'ip-addresses', 'processes', 'json']

    parser.add_argument('--enable', metavar='ENABLED_HIGHLIGHTERS', default=None,
                       help='Enable specific highlighters')
    parser.add_argument('--disable', metavar='DISABLED_HIGHLIGHTERS', default=None,
                       help='Disable specific highlighters')
    parser.add_argument('--disable-builtin-keywords', action='store_true',
                       help='Disable builtin keyword highlighting')
    parser.add_argument('--pager', metavar='PAGER', default=os.environ.get('TAILSPIN_PAGER'),
                       help='Override default pager')
    parser.add_argument('-h', '--help', action='store_true', help='Print help')
    parser.add_argument('-V', '--version', action='store_true', help='Print version')

    args = parser.parse_args()

    if args.version:
        print('tspin 5.6.0')
        sys.exit(0)

    if args.help:
        print_help()
        sys.exit(0)

    return args, ALL_GROUPS


def print_help():
    print("""A log file highlighter

Usage: tspin [OPTIONS] [FILE]

Arguments:
  [FILE]
          Filepath

Options:
  -f, --follow
          Follow the contents of a file

  -p, --print
          Print the output to stdout

      --config-path <CONFIG_PATH>
          Provide a custom path to a configuration file

  -e, --exec <EXEC>
          Run command and view the output in a pager

      --highlight <COLOR_WORD>
          Highlights in the form color:word1,word2

          [possible values: red, green, yellow, blue, magenta, cyan]

      --enable <ENABLED_HIGHLIGHTERS>
          Enable specific highlighters

          [possible values: numbers, urls, pointers, dates, paths, quotes, key-value-pairs, uuids,
          ip-addresses, processes, json]

      --disable <DISABLED_HIGHLIGHTERS>
          Disable specific highlighters

          [possible values: numbers, urls, pointers, dates, paths, quotes, key-value-pairs, uuids,
          ip-addresses, processes, json]

      --disable-builtin-keywords
          Disable the highlighting of all builtin keyword groups (booleans, nulls, log severities
          and common REST verbs)

      --pager <PAGER>
          Override the default pager command used by tspin. (e.g. `--pager="ov -f [FILE]"`)

          [env: TAILSPIN_PAGER=]

  -h, --help
          Print help (see a summary with '-h')

  -V, --version
          Print version""")


def load_config(path):
    """Load TOML config file"""
    if not os.path.exists(path):
        raise ValueError("could not find the TOML file")

    if tomllib is None:
        raise ValueError("TOML support not available (install tomli)")

    with open(path, 'rb') as f:
        try:
            return tomllib.load(f)
        except Exception as e:
            raise ValueError(str(e))


def get_default_config_path():
    xdg_config = os.environ.get('XDG_CONFIG_HOME')
    if xdg_config:
        return os.path.join(xdg_config, 'tailspin', 'theme.toml')
    home = os.environ.get('HOME')
    if home:
        return os.path.join(home, '.config', 'tailspin', 'theme.toml')
    return None


def parse_highlight_args(highlights):
    """Parse --highlight arguments"""
    result = []
    for h in highlights:
        if ':' not in h:
            print(f"Error: Invalid highlight format: {h}", file=sys.stderr)
            sys.exit(1)
        color, words_str = h.split(':', 1)
        valid_colors = ['red', 'green', 'yellow', 'blue', 'magenta', 'cyan']
        if color not in valid_colors:
            print(f"Error: Invalid color: {color}", file=sys.stderr)
            sys.exit(1)
        words = words_str.split(',')
        result.append((color, words))
    return result


def process_stream(reader, hl, writer):
    """Process lines from reader, write highlighted output to writer"""
    for line in reader:
        if isinstance(line, bytes):
            line = line.decode('utf-8', errors='replace')
        line = line.rstrip('\n').rstrip('\r')
        highlighted = hl.highlight_line(line)
        writer.write(highlighted + '\n')
        writer.flush()


def main():
    args, ALL_GROUPS = parse_args()

    # Handle conflicting options
    if args.enable and args.disable:
        print("Error:   \u00d7 cannot both enable and disable highlighters\n", file=sys.stderr)
        sys.exit(1)

    # Determine enabled groups
    if args.enable:
        enabled_groups = set(args.enable.split(','))
    elif args.disable:
        disabled = set(args.disable.split(','))
        enabled_groups = set(ALL_GROUPS) - disabled
    else:
        enabled_groups = set(ALL_GROUPS)

    # Load config
    config = {}
    if args.config_path:
        try:
            config = load_config(args.config_path)
        except ValueError as e:
            print(f"Error:   \u00d7 {e}\n", file=sys.stderr)
            sys.exit(1)
    else:
        default_path = get_default_config_path()
        if default_path and os.path.exists(default_path):
            try:
                config = load_config(default_path)
            except ValueError:
                config = {}

    # Parse highlight args
    custom_highlights = parse_highlight_args(args.highlight)

    # Create highlighter
    hl = Highlighter(config, enabled_groups, custom_highlights, args.disable_builtin_keywords)

    writer = sys.stdout

    if getattr(args, 'exec'):
        # Run command
        cmd = getattr(args, 'exec')
        proc = subprocess.Popen(['sh', '-c', cmd], stdout=subprocess.PIPE, stderr=sys.stderr)
        if proc.stdout:
            if args.print:
                process_stream(proc.stdout, hl, writer)
            else:
                tmp_path = write_to_temp(proc.stdout, hl)
                open_pager(tmp_path, args)
                os.unlink(tmp_path)
        proc.wait()
    elif args.file:
        filepath = args.file
        if args.follow:
            follow_file(filepath, hl, writer)
        else:
            try:
                with open(filepath, 'r', errors='replace') as f:
                    if args.print:
                        process_stream(f, hl, writer)
                    else:
                        tmp_path = write_to_temp(f, hl)
                        open_pager(tmp_path, args)
                        os.unlink(tmp_path)
            except FileNotFoundError:
                print(f"Error: File not found: {filepath}", file=sys.stderr)
                sys.exit(1)
    else:
        # Read from stdin
        process_stream(sys.stdin, hl, writer)


def write_to_temp(reader, hl):
    import tempfile
    fd, tmp_path = tempfile.mkstemp(prefix='tspin-')
    with os.fdopen(fd, 'w') as f:
        for line in reader:
            if isinstance(line, bytes):
                line = line.decode('utf-8', errors='replace')
            line = line.rstrip('\n').rstrip('\r')
            highlighted = hl.highlight_line(line)
            f.write(highlighted + '\n')
    return tmp_path


def open_pager(tmp_path, args):
    if args.pager:
        cmd = args.pager.replace('[FILE]', tmp_path)
    else:
        cmd = f'less -R {tmp_path}'
    subprocess.call(['sh', '-c', cmd])


def follow_file(filepath, hl, writer):
    """Tail -f like following"""
    import time
    try:
        with open(filepath, 'r', errors='replace') as f:
            while True:
                line = f.readline()
                if not line:
                    time.sleep(0.1)
                    continue
                line = line.rstrip('\n').rstrip('\r')
                highlighted = hl.highlight_line(line)
                writer.write(highlighted + '\n')
                writer.flush()
    except KeyboardInterrupt:
        pass


if __name__ == '__main__':
    main()
