        result += ' ' + ansi('}', '2')
        return result
    elif isinstance(value, list):
        result = ansi('[', '2')
        items = [format_json_value(v) for v in value]
        result += (ansi(',', '2') + ' ').join(items)
        result += ansi(']', '2')
        return result
    elif isinstance(value, str):
        return ansi('"', '2') + value + ansi('"', '2')
    elif isinstance(value, bool):
        return ansi(str(value).lower(), '3;31')
    elif value is None:
        return ansi('null', '3;31')
    elif isinstance(value, (int, float)):
        return ansi(str(value), '36')
    else:
        return str(value)


def try_highlight_full_json(line):
    """Try to highlight the entire line as JSON. Returns highlighted string or None."""
    trimmed = line.strip()
    if not trimmed:
        return None
    if trimmed[0] not in '{[':
        return None
    try:
        value = json.loads(trimmed)
    except json.JSONDecodeError:
        return None
    return format_json_value(value)


def colorize_inline_json(text):
    """Color strings in an inline JSON-like structure"""
    result = ''
    i = 0
    chars = list(text)
    in_str = False
    str_start = 0
    while i < len(chars):
        ch = chars[i]
        if not in_str and ch == '"':
            in_str = True
            str_start = i
        elif in_str and ch == '"' and (i == 0 or chars[i-1] != '\\'):
            s = ''.join(chars[str_start:i+1])
            result += ansi(s, '33')
            in_str = False
        elif not in_str:
            result += ch
        i += 1
    return result


# Pattern for inline JSON: at the very minimum a JSON object or array
# We look for { or [ in text, and attempt to match paired braces
def find_inline_json(text):
    """Find JSON-like structures in text"""
    results = []
    i = 0
    while i < len(text):
        ch = text[i]
        if ch in '{[':
            # Try to find the matching close
            close = '}' if ch == '{' else ']'
            depth = 0
            j = i
            in_str = False
            while j < len(text):
                c = text[j]
                if c == '"' and (j == 0 or text[j-1] != '\\'):
                    in_str = not in_str
                elif not in_str:
                    if c == ch or (ch in '([{' and c in '([{'):
                        if c == ch:
                            depth += 1
                    elif c == close:
                        depth -= 1
                        if depth == 0:
                            json_str = text[i:j+1]
                            # Check if it contains at least one quoted string
                            if '"' in json_str:
                                results.append((i, j+1, json_str))
                            i = j + 1
                            break
                j += 1
            else:
                i += 1
        else:
            i += 1
    return results


class Highlighter:
    def __init__(self, config, enabled_groups, custom_highlights, disable_builtin_keywords):
        self.config = config
        self.enabled_groups = enabled_groups
        self.custom_highlights = custom_highlights  # list of (color, [words])
        self.disable_builtin_keywords = disable_builtin_keywords

        # Precompile custom keyword patterns from config
        self.keyword_groups = []
        for kg in config.get('keywords', []):
            words = kg.get('words', [])
            style = kg.get('style', {})
            patterns = [re.compile(re.escape(w)) for w in words]
            self.keyword_groups.append((patterns, style))

    def highlight_line(self, line):
        # Check for full-line JSON
        trimmed = line.strip()
        if trimmed and trimmed[0] in '{[' and 'json' in self.enabled_groups:
            highlighted = try_highlight_full_json(line)
            if highlighted is not None:
                return highlighted

        # Apply all highlighters in order
        segments = [(False, line)]

        # Custom highlights from --highlight flag
        for color, words in self.custom_highlights:
            code = COLOR_MAP.get(color, '37')
            for word in words:
                pat = re.compile(re.escape(word))
                segments = apply_segments(segments, pat, lambda m, c=code: ansi(m.group(0), c))

        # Custom keyword groups from config
        for patterns, style in self.keyword_groups:
            style_code = make_style_code(style)
            if not style_code:
                continue
            has_bg = 'bg' in style and style['bg'] is not None
            for pat in patterns:
                def replacer(m, sc=style_code, hb=has_bg):
                    text = m.group(0)
                    if hb:
                        text = ' ' + text + ' '
                    return ansi(text, sc)
                segments = apply_segments(segments, pat, replacer)

        # HTTP methods (part of builtin keywords)
        if not self.disable_builtin_keywords:
            def http_replacer(m):
                method = m.group(1)
                colors = {'GET': '42;30', 'POST': '43;30', 'PUT': '45;30', 
                          'DELETE': '41;30', 'PATCH': '45;30'}
                color = colors.get(method, '42;30')
                return ansi(f' {method} ', color)
            segments = apply_segments(segments, HTTP_METHOD_RE, http_replacer)

        # Dates
        if 'dates' in self.enabled_groups:
            segments = apply_segments(segments, DATETIME_RE, lambda m: colorize_datetime(m.group(0)))
            segments = apply_segments(segments, SYSLOG_DATE_RE, lambda m: colorize_syslog_date(m.group(0)))
            segments = apply_segments(segments, TIME_ONLY_RE, lambda m: colorize_time(m.group(0)))

        # IP addresses
        if 'ip-addresses' in self.enabled_groups:
            segments = apply_segments(segments, IPV4_RE, lambda m: colorize_ipv4(m.group(0)))
            def ipv6_replacer(m):
                ip = m.group(0)
                if ip.count(':') < 2:
                    return ip
                return colorize_ipv6(ip)
            segments = apply_segments(segments, IPV6_RE, ipv6_replacer)

        # Pointers
        if 'pointers' in self.enabled_groups:
            segments = apply_segments(segments, POINTER_RE, lambda m: colorize_pointer(m.group(0)))

        # UUIDs
        if 'uuids' in self.enabled_groups:
            segments = apply_segments(segments, UUID_RE, lambda m: colorize_uuid(m.group(0)))

        # Processes
        if 'processes' in self.enabled_groups:
            def proc_replacer(m):
                text = m.group(0)
                bracket_pos = text.rfind('[')
                if bracket_pos == -1:
                    return text
                name_part = text[:bracket_pos]
                pid_part = text[bracket_pos+1:-1]
                return (ansi(name_part, '33') + ansi('[', '31') + 
                        ansi(pid_part, '36') + ansi(']', '31'))
            segments = apply_segments(segments, PROCESS_RE, proc_replacer)

        # URLs
        if 'urls' in self.enabled_groups:
            segments = apply_segments(segments, URL_RE, lambda m: colorize_url(m))

        # Paths
        if 'paths' in self.enabled_groups:
            segments = apply_paths_to_segments(segments)

        # Numbers
        if 'numbers' in self.enabled_groups:
            segments = apply_segments(segments, NUMBER_RE, lambda m: ansi(m.group(0), '36'))

        # Severity levels (builtin keywords)
        if not self.disable_builtin_keywords:
            def severity_replacer(m):
                word = m.group(0)
                style_map = {'DEBUG': '32', 'TRACE': '2', 'INFO': '37', 'WARN': '33', 'ERROR': '31'}
                s = style_map.get(word, '37')
                return ansi(word, s)
            segments = apply_segments(segments, SEVERITY_RE, severity_replacer)

        # Boolean/null (builtin keywords)
        if not self.disable_builtin_keywords:
            segments = apply_segments(segments, BOOL_NULL_RE, lambda m: ansi(m.group(0), '3;31'))

        # Key-value pairs
        if 'key-value-pairs' in self.enabled_groups:
            def kv_replacer(m):
                text = m.group(0)
                eq_pos = text.index('=')
                key = text[:eq_pos]
                val = text[eq_pos+1:]
                return ansi(key, '2') + ansi('=', '37') + val
            segments = apply_segments(segments, KV_RE, kv_replacer)

        # Inline JSON
        if 'json' in self.enabled_groups:
            segments = self._apply_inline_json(segments)

        # Quotes
        if 'quotes' in self.enabled_groups:
            segments = self._apply_quotes(segments, line)

        return segments_to_str(segments)

    def _apply_inline_json(self, segments):
        """Apply inline JSON string highlighting"""
        new_segs = []
        for (is_hl, text) in segments:
            if is_hl:
                new_segs.append((True, text))
                continue

            # Find JSON-like structures
            json_spans = find_inline_json(text)
            if not json_spans:
                new_segs.append((False, text))
                continue

            last_end = 0
            for (start, end, json_str) in json_spans:
                if start > last_end:
                    new_segs.append((False, text[last_end:start]))
                new_segs.append((True, colorize_inline_json(json_str)))
                last_end = end
            if last_end < len(text):
                new_segs.append((False, text[last_end:]))

        return new_segs

    def _apply_quotes(self, segments, original_line):
        """Apply quote highlighting"""
        # Check if this is a single-quoted string (only whitespace around it)
        stripped = original_line.strip()
        is_single_only = (
            stripped.startswith('"') and 
            stripped.endswith('"') and 
            len(stripped) > 1 and
            '"' not in stripped[1:-1]
        )

        def replacer(m):
            text = m.group(0)
            if is_single_only and text == stripped:
                # Dim quotes, plain content
                inner = text[1:-1]
                return ansi('"', '2') + inner + ansi('"', '2')
            else:
                return ansi(text, '33')

        return apply_segments(segments, QUOTE_RE, replacer)


def parse_args():
    # Custom argument parsing to match the exact output format
    import sys

    args_list = sys.argv[1:]

    # Handle version and help first
    if '-V' in args_list or '--version' in args_list:
        print('tspin 5.6.0')
        sys.exit(0)

    if '-h' in args_list or '--help' in args_list:
        print_help()
        sys.exit(0)

    # Parse remaining args manually
    result = argparse.Namespace(
        file=None,
        follow=False,
        print=False,
        config_path=None,
        exec=None,
        highlight=[],
        enable=None,
        disable=None,
        disable_builtin_keywords=False,
        pager=os.environ.get('TAILSPIN_PAGER'),
    )

    ALL_GROUPS = ['numbers', 'urls', 'pointers', 'dates', 'paths', 'quotes', 
                  'key-value-pairs', 'uuids', 'ip-addresses', 'processes', 'json']

    i = 0
    while i < len(args_list):
        arg = args_list[i]
        if arg in ('-f', '--follow'):
            result.follow = True
        elif arg in ('-p', '--print'):
            result.print = True
        elif arg == '--disable-builtin-keywords':
            result.disable_builtin_keywords = True
        elif arg in ('--config-path',):
            i += 1
            if i < len(args_list):
                result.config_path = args_list[i]
        elif arg in ('-e', '--exec'):
            i += 1
            if i < len(args_list):
                result.exec = args_list[i]
        elif arg == '--highlight':
            i += 1
            if i < len(args_list):
                result.highlight.append(args_list[i])
        elif arg.startswith('--highlight='):
            result.highlight.append(arg[len('--highlight='):])
        elif arg == '--enable':
            i += 1
            if i < len(args_list):
                result.enable = args_list[i]
        elif arg.startswith('--enable='):
            result.enable = arg[len('--enable='):]
        elif arg == '--disable':
            i += 1
            if i < len(args_list):
                result.disable = args_list[i]
        elif arg.startswith('--disable='):
            result.disable = arg[len('--disable='):]
        elif arg == '--pager':
            i += 1
            if i < len(args_list):
                result.pager = args_list[i]
        elif arg.startswith('--pager='):
            result.pager = arg[len('--pager='):]
        elif not arg.startswith('-'):
            result.file = arg
        else:
            print(f"Error: Unknown argument: {arg}", file=sys.stderr)
            sys.exit(1)
        i += 1

    return result, ALL_GROUPS


def print_help():
    print("""A log file highlighter

Usage: tspin [OPTIONS] [FILE]

Arguments:
  [FILE]
          Filepath

Options:
  -f, --follow
          Follow the contents of a file

  -p, --print
          Print the output to stdout

