def find_paths(text):
    """Find file path matches in text, returning list of (start, end, matched_text)"""
    results = []

    # Match paths with at least 2 slashes (counting from start)
    # Pattern for absolute paths starting with /
    # /component/component (at least)
    abs_pat = re.compile(r'/[^\s/,;)\'\"]+(?:/[^\s,;)\'\"]*)*')

    # Pattern for ~ paths
    tilde_pat = re.compile(r'~(?:/[^\s/,;)\'\"]+){2,}/?')

    # Pattern for relative paths with ./ or ../
    rel_dot_pat = re.compile(r'\.\.?/[^\s/,;)\'\"]*(?:/[^\s,;)\'\"]*)+')

    # Pattern for other relative paths (word/word/word)
    rel_pat = re.compile(r'[^\s/,;)\'\"]+(?:/[^\s/,;)\'\"]+){2,}')

    for pat in [abs_pat, tilde_pat, rel_dot_pat]:
        for m in pat.finditer(text):
            path = m.group(0)
            # Count slashes
            slash_count = path.count('/')
            if pat == abs_pat:
                # /a/b needs at least 2 slashes total (the one at start + at least 1 more)
                if slash_count < 2:
                    continue
            elif pat == tilde_pat:
                # ~/a/b needs at least 2 slashes
                if slash_count < 2:
                    continue
