    for m in rel_pat.finditer(text):
        path = m.group(0)
        if path.count('/') >= 2:
            results.append((m.start(), m.end(), path))

    # Sort and deduplicate
    results.sort(key=lambda x: x[0])

    # Remove overlapping
    final = []
    last_end = 0
    for (start, end, path) in results:
        if start >= last_end:
            final.append((start, end, path))
            last_end = end

    return final


